"""Compute PSNR and LPIPS on a samples.npz generated by rfid_adm.py (or similar).

Compares reconstructed images (samples.npz) against the ImageNet validation
reference (auto-downloaded). Both are uint8 NHWC. Image resolution is inferred
from the samples.

Usage:
    python -m pooldino.eval.samples_metrics \
        --samples output/decoders/RUN/reconstructions/samples.npz

    # With explicit reference
    python -m pooldino.eval.samples_metrics \
        --samples output/decoders/RUN/reconstructions/samples.npz \
        --reference ~/.cache/adm/imagenet256_val.npz
"""

import json
from dataclasses import dataclass
from pathlib import Path

import jax

jax.config.update("jax_default_matmul_precision", "float32")

import flax.nnx as nnx
import jax.numpy as jnp
import numpy as np
import tyro
from absl import logging
from jax.sharding import NamedSharding, PartitionSpec as P
from tqdm import tqdm

from lpips_nnx import LPIPS
from pooldino.external.adm import get_imagenet_val


@dataclass
class Config:
    samples: Path
    """Path to samples.npz (arr_0 key, uint8 NHWC)."""

    reference: Path | None = None
    """Path to reference NPZ. Auto-downloaded from ImageNet val if not set."""

    batch_size: int = 64
    """Batch size for LPIPS computation."""

    seed: int = 0


@nnx.jit
def _compute_batch(
    recon: jax.Array,
    ref: jax.Array,
    lpips_model: LPIPS,
) -> tuple[jax.Array, jax.Array]:
    """Compute per-sample PSNR and LPIPS for a batch of float32 [0,1] images."""
    mse = jnp.mean(jnp.square(recon - ref), axis=(1, 2, 3))
    psnr = -10.0 * jnp.log10(jnp.maximum(mse, 1e-10))
    lpips = lpips_model(recon * 2.0 - 1.0, ref * 2.0 - 1.0)
    return psnr, lpips


def main(cfg: Config) -> None:
    mesh = jax.make_mesh((jax.device_count(), 1), ("data", "model"))
    jax.set_mesh(mesh)

    # Load samples
    logging.info(f"Loading samples from {cfg.samples}")
    samples = np.load(cfg.samples)["arr_0"]
    logging.info(f"Samples: {samples.shape}, dtype={samples.dtype}")
    image_size = samples.shape[1]

    # Load or auto-download reference
    ref_path = cfg.reference or get_imagenet_val(image_size)
    logging.info(f"Loading reference from {ref_path}")
    reference = np.load(ref_path)["arr_0"]
    logging.info(f"Reference: {reference.shape}, dtype={reference.dtype}")

    num_samples = min(samples.shape[0], reference.shape[0])
    if samples.shape[0] != reference.shape[0]:
        logging.warning(
            f"Sample count mismatch: {samples.shape[0]} samples vs {reference.shape[0]} reference. "
            f"Using first {num_samples}."
        )
    samples = samples[:num_samples]
    reference = reference[:num_samples]

    if samples.shape[1:] != reference.shape[1:]:
        raise ValueError(
            f"Shape mismatch: samples {samples.shape[1:]} vs reference {reference.shape[1:]}"
        )

    lpips_model = LPIPS(rngs=nnx.Rngs(cfg.seed))
    shard = NamedSharding(mesh, P("data"))

    psnr_all: list[np.ndarray] = []
    lpips_all: list[np.ndarray] = []

    for start in tqdm(range(0, num_samples, cfg.batch_size), desc="Computing metrics"):
        end = min(start + cfg.batch_size, num_samples)
        batch_len = end - start

        recon_np = samples[start:end].astype(np.float32) / 255.0
        ref_np = reference[start:end].astype(np.float32) / 255.0

        # Pad to device count
        n_devices = jax.device_count()
        pad_size = (n_devices - batch_len % n_devices) % n_devices
        if pad_size > 0:
            recon_np = np.concatenate([recon_np, np.repeat(recon_np[-1:], pad_size, axis=0)])
            ref_np = np.concatenate([ref_np, np.repeat(ref_np[-1:], pad_size, axis=0)])

        recon_jax = jax.device_put(jnp.array(recon_np), shard)
        ref_jax = jax.device_put(jnp.array(ref_np), shard)

        psnr, lpips = _compute_batch(recon_jax, ref_jax, lpips_model)
        psnr_np = np.asarray(psnr)
        lpips_np = np.asarray(lpips)

        if pad_size > 0:
            psnr_np = psnr_np[:-pad_size]
            lpips_np = lpips_np[:-pad_size]

        psnr_all.append(psnr_np)
        lpips_all.append(lpips_np)

    psnr_values = np.concatenate(psnr_all)
    lpips_values = np.concatenate(lpips_all)

    logging.info(f"Evaluated {num_samples} image pairs")
    logging.info("")
    logging.info(f"{'Metric':<10}{'Mean':>12}{'Std':>12}")
    logging.info(f"{'PSNR':<10}{np.mean(psnr_values):>12.4f}{np.std(psnr_values):>12.4f}")
    logging.info(f"{'LPIPS':<10}{np.mean(lpips_values):>12.4f}{np.std(lpips_values):>12.4f}")

    # Save results next to samples.npz
    results = {
        "num_samples": int(num_samples),
        "psnr_mean": float(np.mean(psnr_values)),
        "psnr_std": float(np.std(psnr_values)),
        "lpips_mean": float(np.mean(lpips_values)),
        "lpips_std": float(np.std(lpips_values)),
    }
    results_path = cfg.samples.parent / "samples_metrics.json"
    with open(results_path, "w") as f:
        json.dump(results, f, indent=2)
    logging.info(f"Saved results to {results_path}")


if __name__ == "__main__":
    logging.set_verbosity(logging.INFO)
    cfg = tyro.cli(Config)
    main(cfg)
